PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?nombre WHERE {
  { SELECT ?c (SUM(?oil) AS ?total) WHERE {
      ?p a energia:UnconventionalProduction ; energia:declaredBy ?c ; energia:oil ?oil .
    } GROUP BY ?c }
  ?c energia:name ?nombre .
}
ORDER BY DESC(?total)
LIMIT 5
